def transform(g):
    h,w=len(g),len(g[0])
    out=[row[:] for row in g]
    threes=[(r,c) for r in range(h) for c in range(w) if g[r][c]==3]
    for r,c in threes:
        for dc in range(-2,3):
            if 0<=r-2<h and 0<=c+dc<w: out[r-2][c+dc]=5
            for rr in (r-1,r,r+1):
                for cc in (c-2,c+2):
                    if 0<=rr<h and 0<=cc<w: out[rr][cc]=2
            if 0<=r-1<h and 0<=c+dc<w: out[r-1][c+dc]=5
        if 0<=r+2<h:
            for cc in range(w):
                out[r+2][cc]=8 if abs(cc-c)<=2 else 2
    return out

